abap-m11-quellen-assoziation-oder-join-b.code:
// Voraussetzung: ZI_LearnCustomer mit CustomerID und Name
@EndUserText.label: 'Reisen mit Kundenbeziehung'
define view entity ZI_LearnTravelRel
  as select from zlearn_travel
  association [0..1] to ZI_LearnCustomer as _Customer
    on $projection.CustomerID = _Customer.CustomerID
{
  key travel_id   as TravelID,
      customer_id as CustomerID,
      description as Description,
      // _Customer.Name as CustomerName,
      _Customer
}

abap-m11-quellen-annotationen-sinnvoll-e.code:
// Voraussetzung: total_price ist ein Betragsfeld, currency_code ein Währungsfeld
@EndUserText.label: 'Reisepreise mit Währung'
define view entity ZI_LearnTravelPrice
  as select from zlearn_travel
{
  key travel_id as TravelID,
      @Semantics.amount.currencyCode: 'CurrencyCode'
      total_price as TotalPrice,
      currency_code as CurrencyCode
}

